q(){ curl -s -G "https://www.federalregister.gov/api/v1/documents.json" --data-urlencode "conditions[term]=$1" --data-urlencode "per_page=${2:-15}" --data-urlencode "order=newest" --data-urlencode "conditions[publication_date][gte]=${3:-2000-01-01}" -d "fields[]=citation" -d "fields[]=publication_date" -d "fields[]=effective_on" -d "fields[]=title" -d "fields[]=html_url" -d "fields[]=type" -d "fields[]=document_number" | python3 -c "import json,sys;d=json.load(sys.stdin);print('count',d.get('count'));[print(r['publication_date'],r.get('citation'),r.get('effective_on'),r['type'],r['title'][:170],r['html_url']) for r in d.get('results',[])]"; }
